def _replace_checks(
    before: dict[str, list[tuple[str, str]]], after: dict[str, list[tuple[str, str]]]
) -> None:
    """Меняет CHECK явно: autogenerate не обнаруживает все такие изменения."""

    for table, constraints in before.items():
        for name, _ in constraints:
            op.drop_constraint(op.f(name), table, type_="check")
    for table, constraints in after.items():
        for name, expression in constraints:
            op.create_check_constraint(op.f(name), table, expression)
